<section class="card cc-no-print"><div class="cc-row cc-between"><h2>Original Receipt #<?=(int)$source['original']['id']?> · <?=access_h($source['booking']['guest_name'])?></h2><span><?=access_h($source['booking']['status']==='checked_out'?'Checked Out':'In House')?></span></div><p>Room <?=access_h($source['booking']['room_name'])?> · Stay #<?=(int)$source['booking']['id']?></p><dl class="cc-totals"><div><dt>Original Receipt</dt><dd><?=access_h(cc_money(\Tivoli\Domain\Stay\StayRules::minor($source['original']['amount'])))?></dd><p><?=access_h(strtoupper($source['original']['method']).' · '.($source['original']['reference_no']??'Not Recorded'))?></p></div><div><dt>Recorded By / At</dt><dd><?=access_h($source['original']['actor_name']??'Historical Actor Unknown')?></dd><p><?=access_h(display_date($source['original']['created_at']))?> UTC</p></div><div><dt>Current Effective Receipt</dt><dd><?=access_h(cc_money($source['position']['amount']))?></dd><p><?=access_h(strtoupper($source['position']['method']).' · '.$source['position']['reference'])?></p></div></dl><p>Original Activity: <?=access_h(display_date($source['original_date']))?> · <?=$source['original_locked']?'Original Accounting Period Locked':'Original Accounting Period Open'?>. Corrections post in today's open period.</p><?php if($source['refunded']):?><p class="cc-warning">Already refunded: <?=access_h(cc_money($source['refunded']))?>. This remains linked and limits the correction.</p><?php endif;foreach($source['blockers'] as $blocker):?><p class="cc-warning"><?=access_h($blocker)?></p><?php endforeach?><?php if($source['collection_id']!==(int)$source['original']['id']):?><a class="cc-button" href="<?=access_h(cc_url(['payment_id'=>$source['collection_id']]))?>#correction-action">Open Retained Collection Receipt #<?=(int)$source['collection_id']?></a><?php endif?><a href="<?=access_h(access_url('occupancy.php?booking_id='.(int)$source['booking']['id'].'&tab=payments'))?>#stay-bill">Show Guest Stay Account</a></section>

<?php if($source['dependencies']):?><section class="card cc-no-print"><h2>Existing Linked Money</h2><p>Reconcile these records in the correction form below. Their original actual amounts and history remain fixed.</p><?php foreach($source['dependencies'] as $dep):if(!in_array($dep['kind'],['deposit_recorded','cash_transfer_sent','receipt_matched','cd_credit','ra_wallet_in','ra_wallet_out'],true))continue;?><p>#<?=(int)$dep['id']?> · <?=access_h(cc_movement_label($dep['kind']))?> · <?=access_h(cc_money((int)$dep['amount_minor']))?></p><?php endforeach?></section><?php endif?>
